import{z as i,x as l,o as E,c as T,q as n,j as A,D as e,d as t,s as o,S as B,b as s}from"./chunks/framework.C8m1ZpeB.js";const U=JSON.parse('{"title":"QUIC 对照","description":"","frontmatter":{"title":"QUIC 对照","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/quic-contrast.md","filePath":"cs/quic-contrast.md","lastUpdated":1791063341000}'),C={name:"cs/quic-contrast.md"};function d(p,a,P,D,c,h){const r=l("Mermaid");return E(),T("div",null,[a[2]||(a[2]=n('<h1 id="quic-对照" tabindex="-1">QUIC 对照 <a class="header-anchor" href="#quic-对照" aria-label="Permalink to &quot;QUIC 对照&quot;">​</a></h1><div class="epigraph"><p>QUIC 在 UDP 上做可靠流、拥塞控制与加密握手，避免 TCP 队头阻塞与内核握手的往返。</p><footer>—— 据 Iyengar and Thomson, RFC 9000, QUIC: A UDP-Based Multiplexed and Secure Transport, 2021 整理</footer></div><p><a href="/cs/bbr">上一课</a>让 TCP 能共用瓶颈。<a href="/cs/tcp-handshake">三次握手</a>之后若还要 TLS，往返再加。<a href="/cs/tcp-seq-rexmit">序号</a>在一条字节流上，丢失一块会挡住后面已到的流——HTTP/2 多流仍队头阻塞。缺口是对照：<strong>QUIC</strong> 把多路可靠流放到 UDP，加密默认在传输里。本课不写 TLS 记录层握手细节。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TCP 中途的字节是一条全序流：段丢失，后续不能交给应用，即使它们属于另一 HTTP 事务。<span class="marginnote">术语翻译：队头阻塞就是「排在最前面的数据卡住，后面即使先到也放行不了」的现象——像收银台前第一个人翻钱包，后面买好单的人全都干等。</span>内核改 TCP 部署慢。RFC 9000：连接 ID、包号与流 ID 分离，丢包只挡一条流；握手与密钥在 QUIC 包里完成（1-RTT，有时 0-RTT）。缺口是这些对照，不是再推导 AIMD。</p><p>拥塞控制仍在，只是实现移到用户库，信号仍是丢/标记。</p><p><span class="marginnote">UDP 让 NAT 与中间盒把 QUIC 当数据报。连接 ID 允许换 IP 而不拆连接，对照 TCP 四元组绑死。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>应用打开 QUIC 连接（库内部 UDP 套接字）。多流并行，每流有序，流之间无全序。丢失用包号重传，不把包号当成 TCP 那种字节序号。本课不把帧类型清单背完。与<a href="/cs/http">HTTP</a> 的接头在 HTTP/3：同一对象模型换传输。</p>',9)),(E(),A(B,null,{default:e(()=>[o(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20TCP%5B%22TCP%3A%20%E5%8D%95%E5%AD%97%E8%8A%82%E6%B5%81%20%2B%20%E5%8F%AF%E9%80%89%E5%A4%96%E6%8C%82%20TLS%22%5D%20--%3E%20CMP%5B%22%E5%AF%B9%E7%85%A7%22%5D%0A%20%20QUIC%5B%22QUIC%3A%20UDP%20%E4%B8%8A%E5%A4%9A%E6%B5%81%20%2B%20%E5%86%85%E7%BD%AE%E5%8A%A0%E5%AF%86%22%5D%20--%3E%20CMP%0A%20%20CMP%20--%3E%20APP%5B%22%E5%BA%94%E7%94%A8%E4%BB%8D%E8%A7%81%E5%8F%AF%E9%9D%A0%E6%B6%88%E6%81%AF%2F%E6%B5%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"队头阻塞从「连接级」降到「流级」，符合多请求并行。端到端加密让中间盒看不见传输头——运维抓包变难，安全课再谈；本课只说明为何握手不能再裸露三次 ACK。拥塞：一条 QUIC 连接内多流共享 cwnd，避免每个浏览器流一条 TCP 时的过于激进。",-1)),(E(),A(B,null,{default:e(()=>[o(r,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20LA%5B%22%E6%B5%811%20%E4%B8%A2%E5%8C%85%22%5D%20--%3E%20T%5B%22TCP%EF%BC%9A%E5%8D%95%E6%9D%A1%E5%85%A8%E5%BA%8F%E5%AD%97%E8%8A%82%E6%B5%81%22%5D%0A%20%20LB%5B%22%E6%B5%812%20%E6%95%B0%E6%8D%AE%E5%B7%B2%E5%88%B0%22%5D%20--%3E%20T%0A%20%20T%20--%3E%20TB%5B%22%E6%B5%812%20%E4%B9%9F%E8%A2%AB%E6%8C%A1%E4%BD%8F%EF%BC%9A%E8%BF%9E%E6%8E%A5%E7%BA%A7%E9%98%9F%E5%A4%B4%E9%98%BB%E5%A1%9E%22%5D%0A%20%20QA%5B%22%E6%B5%811%20%E4%B8%A2%E5%8C%85%22%5D%20--%3E%20Q%5B%22QUIC%EF%BC%9A%E6%B5%81%E9%97%B4%E7%8B%AC%E7%AB%8B%E6%9C%89%E5%BA%8F%22%5D%0A%20%20QB%5B%22%E6%B5%812%20%E6%95%B0%E6%8D%AE%E5%B7%B2%E5%88%B0%22%5D%20--%3E%20Q%0A%20%20Q%20--%3E%20OK%5B%22%E6%B5%812%20%E7%85%A7%E5%B8%B8%E4%BA%A4%E4%BB%98%EF%BC%9A%E5%8F%AA%E6%9C%89%E6%B5%811%20%E7%AD%89%E9%87%8D%E4%BC%A0%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">数字实例：TCP 三次握手 1 个 RTT，TLS 1.3 再加 1 个 RTT，首字节之前要 \\(2\\) 个往返；QUIC 把传输与加密握手合并成 1 个 RTT，复用过的连接还能 0-RTT 直接发数据——高延迟链路上每个 RTT 都可能上百毫秒。</span></p><p>与<a href="/cs/semaphore">信号量</a>无关：这里的「流」不是 OS 线程。进程仍用后课套接字，只是协议是 UDP。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把 RFC 9001 的 TLS 映射逐步展开——完整握手在<a href="/cs/tls-handshake">后课 TLS</a>。不引入 HTTP/3 帧与 QPACK。<span class="marginnote">初学者容易以为「QUIC 在 UDP 上跑，所以一定比 TCP 快」；实际上快慢取决于丢包修复与用户态实现的 CPU 开销——UDP 只是给了绕开内核僵化与队头阻塞的出口，不是免检通道。</span>也不声称 UDP 总比 TCP 快：丢失修复与 CPU 实现决定。应用如何用名字找 IP，下一课 DNS。</p><p>0-RTT 数据可能被重放，应用要自己幂等。这是安全与传输的交界，握手课再收，本课只对照延迟。</p><p>用户态实现让拥塞算法可随应用更新，不必等内核发行版，这是部署动机之一。</p><p>后课默认：可靠传输可以是 TCP 或 QUIC。人用的名字如何变成地址，下一课 DNS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>QUIC（RFC 9000）对照 TCP：UDP、多流、连接 ID、加密绑定。</li><li>拥塞思想仍在；队头阻塞范围缩小。</li><li>TLS 握手细节是安全课；本课只要求「传输自带认证加密通道」。</li><li>出处：RFC 9000；Kurose and Ross 新版对 QUIC 的讨论。</li></ul>',9))])}const u=i(C,[["render",d]]);export{U as __pageData,u as default};
